# Sample Prism configuration - customize before using
#
# This file is generated by the prism:install generator.
# Edit the configuration below to match your host application setup.

Prism.configure do |config|
  # Database connection configuration
  # Connections allow Prism to query your database. Each connection is identified by a unique slug.
  # For production, the connection should use a read-only role.
  config.connection :production do |connection|
    connection.adapter = :postgresql
    connection.reuse_host_pool = false
    connection.credentials_file = Pathname.new("secrets/database.yml")
    connection.read_only_role = "prism_ro"
    connection.pool_size = 5
    connection.statement_timeout = 30
    connection.default = true
  end

  # Visibility configuration
  # Determines which schemas, tables, and columns are visible to users.
  config.visibility.mode = :denylist
  config.visibility.allowlist = Set.new(%w[public])
  config.visibility.denylist = Prism::Configuration::VisibilityConfig::SYSTEM_DENYLIST + %w[
    # Add table names to hide from users
  ]

  # Query limits
  config.query.max_rows = 10_000
  config.query.timeout = 30
  config.query.rate_limit = 60
  config.query.statement_timeout = 30
  config.query.enable_explain = true

  # Cache configuration
  # TTL profiles for different cache types
  config.cache.ttl_profiles = {
    dashboard_widget: 30,
    schema: 3600,
    ai_context: 600,
    query_result: 60
  }

  # AI configuration
  # Set enabled to true after configuring your AI provider
  config.ai.enabled = false
  config.ai.provider = :openai
  config.ai.model = "gpt-4o-mini"
  config.ai.api_key_file = Pathname.new("secrets/openai_api_key.txt")
  config.ai.max_tokens = 4000
  config.ai.temperature = 0.1
  config.ai.rate_limit = 20

  # Dashboard configuration
  config.dashboard.min_refresh_interval = 30
  config.dashboard.max_widgets = 50
  config.dashboard.default_theme = :dark
  config.dashboard.grid_columns = 12

  # Sharing configuration
  config.sharing.token_length = 32
  config.sharing.default_expiry = 30 * 24 * 60 * 60
  config.sharing.max_expiry = 365 * 24 * 60 * 60

  # Secrets configuration
  config.secrets.directory = Pathname.new("secrets")
  config.secrets.key_file = Pathname.new("secrets/key.bin")

  # Authentication: Owner resolver
  # This proc resolves the authenticated owner from the current request.
  # The owner is a polymorphic reference (id + type).
  config.owner_resolver = lambda do |request|
    # Replace this with your application's authentication lookup
    # Example for Devise:
    #   user = warden_user(request)
    #   { id: user.id, type: user.class.name }
    #
    # Example for Cookie-based auth:
    #   session = request.session
    #   user_id = session[:user_id]
    #   { id: user_id, type: "User" }

    { id: nil, type: nil }
  end

  # Authentication: Auth guard
  # This proc determines if the current request is authenticated.
  # Return true if authenticated, false otherwise.
  config.auth_guard = lambda do |request|
    # Replace this with your application's authentication check
    # Example:
    #   !warden_user(request).nil?
    false
  end
end